function matches(task: Task, words: string[]): boolean {
  if (words.length === 0) return true
  const fields = [task.id, task.title, task.description, task.assignee].join(' ')
  return words.every((word) => fields.includes(word))
}

export function filterTasks(
  tasks: Task[],
  status: 'all' | TaskStatus,
  assignee: 'all' | string
): Task[] {
  let result = [...tasks]
  if (status !== 'all') result = result.filter(task => task.status === status)
  if (assignee !== 'all') result = result.filter(task => task.assignee === assignee)
  return result
}

export function filteredTasks(
  tasks: Task[],
  searchQuery: string,
  status: 'all' | TaskStatus,
  assignee: 'all' | string
): Task[] {
  if (!searchQuery || !searchQuery.trim()) {
    return filterTasks(tasks, status, assignee)
  }
  const normalizedWords = normalizeSearch(splitQuery(searchQuery))
  const matched = tasks.filter(task => matches(task, normalizedWords))
  return filterTasks(matched, status, assignee)
}

