// Helper function to apply filters
function applyFilters(tasks: Task[], filters: TaskFiltersState): Task[] {
  let result = [...tasks]

  // Apply search filter
  if (filters.searchQuery && filters.searchQuery.trim() !== '') {
    const normalizedQuery = filters.searchQuery.toLowerCase()
    const searchWords = normalizedQuery.split(/\s+/).filter(Boolean)

    result = result.filter(task => {
      const combinedText = `${task.id} ${task.title} ${task.description} ${task.assignee}`.toLowerCase()
      return searchWords.every(word => combinedText.includes(word))
    })
  }

  // Apply status filter
  if (filters.selectedStatus !== 'all') {
    result = result.filter(task => task.status === filters.selectedStatus)
  }

  // Apply assignee filter
  if (filters.selectedAssignee !== 'all') {
    result = result.filter(task => task.assignee === filters.selectedAssignee)
  }

  return result
}

